class Solution:
    def minMovesToCaptureTheQueen(self, a, b, c, d, e, f):
        if a == e and not (c == a and min(b, f) < d < max(b, f)):
            return 1
        if b == f and not (d == b and min(a, e) < c < max(a, e)):
            return 1
        if abs(c - e) == abs(d - f) and not (abs(a - e) == abs(b - f) and min(c, e) < a < max(c, e)):
            return 1
        return 2

